(3287704, 457574, 64352, '<td valign="top">I''ll go ahead and give this one a 10 because not only does it show the minimalism theme but it also is simple by nature and design.</td>', 'I''ll go ahead and give this one a 10 because not only does it show the minimalism theme but it also is simple by nature and design.', '2007-01-26 16:01:32.000000', NULL, 1),
(3287720, 456114, 65779, '<td valign="top">This is great - has the feel of a painting.</td>', 'This is great - has the feel of a painting.', '2007-01-26 16:04:10.000000', NULL, 1),
(3287746, 457549, 65779, '<td valign="top">Perhaps a bit too subtle on the shadow but I still like it.</td>', 'Perhaps a bit too subtle on the shadow but I still like it.', '2007-01-26 16:06:52.000000', NULL, 1),
(3287864, 457961, 56672, '<td valign="top">The elk totally disappears into the background.  I knew I was missing something, but I hate to search to find it.</td>', 'The elk totally disappears into the background.  I knew I was missing something, but I hate to search to find it.', '2007-01-26 16:30:02.000000', NULL, 1),
(3287876, 457591, 56672, '<td valign="top">This would have worked better for me with a steeper angle from the left.  As is, the slight rotation and slant seem unintentional.</td>', 'This would have worked better for me with a steeper angle from the left.  As is, the slight rotation and slant seem unintentional.', '2007-01-26 16:32:33.000000', NULL, 1),
(3287883, 455834, 56672, '<td valign="top">You got the focus right on the bracelet, but for some reason it refuses to draw me in as the subject of the photo.</td>', 'You got the focus right on the bracelet, but for some reason it refuses to draw me in as the subject of the photo.', '2007-01-26 16:34:57.000000', NULL, 1),
(3287891, 457038, 56672, '<td valign="top">It''s a little too subtle, I think.  The contrail blends in a little too much and tends not to draw the eye.</td>', 'It''s a little too subtle, I think.  The contrail blends in a little too much and tends not to draw the eye.', '2007-01-26 16:36:51.000000', NULL, 1),
(3287910, 456006, 56672, '<td valign="top">He''s just too large in the frame for me to feel the minimalism.  Yes, he is small, but there''s no real conveyance of his size in the photo.</td>', 'He''s just too large in the frame for me to feel the minimalism.  Yes, he is small, but there''s no real conveyance of his size in the photo.', '2007-01-26 16:40:04.000000', NULL, 1),
(3287915, 457430, 43565, '<td valign="top">I think this would have worked with a solid background.</td>', 'I think this would have worked with a solid background.', '2007-01-26 16:41:21.000000', NULL, 1),
(3287921, 455362, 56672, '<td valign="top">The photo''s very busy - nothing calls itself out as the definite subject.  The blow-out, haze, and lack of distinct focus over the image don''t do anything for me.</td>', 'The photo''s very busy - nothing calls itself out as the definite subject.  The blow-out, haze, and lack of distinct focus over the image don''t do anything for me.', '2007-01-26 16:42:00.000000', NULL, 1),
(3287922, 458703, 43565, '<td valign="top">I like the textures.</td>', 'I like the textures.', '2007-01-26 16:42:22.000000', NULL, 1),
(3287936, 455393, 56672, '<td valign="top">I find the slight visual rotation distracting (you were probably just slightly to an angle with the wall), but nothing to lose points over.  Nice concept.</td>', 'I find the slight visual rotation distracting (you were probably just slightly to an angle with the wall), but nothing to lose points over.  Nice concept.', '2007-01-26 16:44:55.000000', NULL, 1),
(3287945, 458036, 56672, '<td valign="top">My only issue is the lens flare.  A lens hood or shielding with your hand would have been a good idea.</td>', 'My only issue is the lens flare.  A lens hood or shielding with your hand would have been a good idea.', '2007-01-26 16:46:34.000000', NULL, 1),
(3287951, 457681, 43565, '<td valign="top">That is a LOT of ice!</td>', 'That is a LOT of ice!', '2007-01-26 16:47:22.000000', NULL, 1),
(3287956, 458445, 65779, '<td valign="top">There is some weird stuff going on in the sky there and I don''t think they are UFOs.</td>', 'There is some weird stuff going on in the sky there and I don''t think they are UFOs.', '2007-01-26 16:48:16.000000', NULL, 1),
(3287957, 457884, 56672, '<td valign="top">Could have used the tiniest bit more lighting to get the right leg to show.  Right now it''s invisible against the background.</td>', 'Could have used the tiniest bit more lighting to get the right leg to show.  Right now it''s invisible against the background.', '2007-01-26 16:48:23.000000', NULL, 1),
