(3289703, 457490, 71767, '<td valign="top">I''m not sure I like the composition.</td>', 'I''m not sure I like the composition.', '2007-01-27 01:21:20.000000', NULL, 1),
(3289704, 456114, 71767, '<td valign="top">It definitely meets the challenge.</td>', 'It definitely meets the challenge.', '2007-01-27 01:22:24.000000', NULL, 1),
(3289705, 458655, 71767, '<td valign="top">I''m not totally convinced this is a minimalist shot</td>', 'I''m not totally convinced this is a minimalist shot', '2007-01-27 01:22:49.000000', NULL, 1),
(3289707, 456805, 71767, '<td valign="top">Subject is a bit dull.</td>', 'Subject is a bit dull.', '2007-01-27 01:23:05.000000', NULL, 1),
(3289708, 458653, 71767, '<td valign="top">Not the most exciting subject...</td>', 'Not the most exciting subject...', '2007-01-27 01:23:29.000000', NULL, 1),
(3289713, 458835, 71767, '<td valign="top">Background is somewhat distracting.</td>', 'Background is somewhat distracting.', '2007-01-27 01:24:10.000000', NULL, 1),
(3289718, 456268, 71767, '<td valign="top">I''m not sure if this is really a minimalist shot. what is the main subject here?</td>', 'I''m not sure if this is really a minimalist shot. what is the main subject here?', '2007-01-27 01:25:43.000000', NULL, 1),
(3289720, 457952, 71767, '<td valign="top">nicely done.</td>', 'nicely done.', '2007-01-27 01:26:03.000000', NULL, 1),
(3289727, 456846, 71767, '<td valign="top">truly minimalistic</td>', 'truly minimalistic', '2007-01-27 01:28:08.000000', NULL, 1),
(3289731, 458740, 71767, '<td valign="top">Nice image. Sensor dust is a bit distracting.</td>', 'Nice image. Sensor dust is a bit distracting.', '2007-01-27 01:30:54.000000', NULL, 1),
(3289739, 458445, 71767, '<td valign="top">seems like your sensor could use some cleaning :D very distracting dust spots work against a nice image.</td>', 'seems like your sensor could use some cleaning :D very distracting dust spots work against a nice image.', '2007-01-27 01:34:10.000000', NULL, 1),
(3289741, 458827, 71767, '<td valign="top">I''m not convinced this meets the theme minimalism...</td>', 'I''m not convinced this meets the theme minimalism...', '2007-01-27 01:34:59.000000', NULL, 1),
(3289781, 455688, 71767, '<td valign="top">Wow, how did you do that?</td>', 'Wow, how did you do that?', '2007-01-27 01:52:12.000000', NULL, 1),
(3289858, 457419, 47096, '<td valign="top">A bit underexposed.</td>', 'A bit underexposed.', '2007-01-27 02:25:35.000000', NULL, 1),
(3289905, 457878, 64670, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2007-01-27 02:57:36.000000', NULL, 1),
(3289914, 457878, 32872, '<td valign="top">Lovely tones.  Whispery and magical.</td>', 'Lovely tones.  Whispery and magical.', '2007-01-27 02:59:29.000000', NULL, 1),
(3289916, 458706, 32872, '<td valign="top">Nice image.</td>', 'Nice image.', '2007-01-27 03:00:36.000000', NULL, 1),
(3289922, 458166, 32872, '<td valign="top">Ouch...makes me want to cry!  Not your image, just the object itself!  Nice DOF. :)</td>', 'Ouch...makes me want to cry!  Not your image, just the object itself!  Nice DOF. :)', '2007-01-27 03:03:08.000000', NULL, 1),
(3290005, 458224, 48228, '<td valign="top">I love this one, a lot.....</td>', 'I love this one, a lot.....', '2007-01-27 03:59:01.000000', NULL, 1),
