INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3290030, 455892, 48228, '<td valign="top">Love ths one.....</td>', 'Love ths one.....', '2007-01-27 04:19:13.000000', NULL, 1),
(3290034, 458643, 48228, '<td valign="top">Just beautiful.....</td>', 'Just beautiful.....', '2007-01-27 04:21:21.000000', NULL, 1),
(3290040, 458342, 48228, '<td valign="top">I really like this one with the rich night colors.....</td>', 'I really like this one with the rich night colors.....', '2007-01-27 04:27:50.000000', NULL, 1),
(3290041, 456114, 48228, '<td valign="top">perfect for Minimalism.....IMO.....</td>', 'perfect for Minimalism.....IMO.....', '2007-01-27 04:28:19.000000', NULL, 1),
(3290043, 455672, 48228, '<td valign="top">Simply done, and it works.....IMO.....</td>', 'Simply done, and it works.....IMO.....', '2007-01-27 04:30:00.000000', NULL, 1),
(3290044, 455389, 48228, '<td valign="top">Perfect in everyway and top votes from me.....</td>', 'Perfect in everyway and top votes from me.....', '2007-01-27 04:30:43.000000', NULL, 1),
(3290046, 458783, 46314, '<td valign="top">I like the angle you used - adds some drama to the photo. Would have been more lifeless if it were straight on.</td>', 'I like the angle you used - adds some drama to the photo. Would have been more lifeless if it were straight on.', '2007-01-27 04:35:41.000000', NULL, 1),
(3290047, 458587, 46314, '<td valign="top">Might have enhanced he feeling of minimalism if you''d arranged it so that only the lower third was steel table, and the top two thirds were the white wall background. These type of minimalist shots are usually good practice for the rule-of-thirds law.</td>', 'Might have enhanced he feeling of minimalism if you''d arranged it so that only the lower third was steel table, and the top two thirds were the white wall background. These type of minimalist shots are usually good practice for the rule-of-thirds law.', '2007-01-27 04:37:43.000000', NULL, 1),
(3290049, 458299, 46314, '<td valign="top">The lamppost and white line in the lower left are a bit distracting, but overall I like the mood here - feels like a deserted street, lonely man, head down. Quite unassuming and minimalist.</td>', 'The lamppost and white line in the lower left are a bit distracting, but overall I like the mood here - feels like a deserted street, lonely man, head down. Quite unassuming and minimalist.', '2007-01-27 04:39:08.000000', NULL, 1),
(3290053, 458234, 46314, '<td valign="top">The scene could have been composed better. Maybe brought the subject down to the bottom third of the image, where it would have been placed stronger. Also, although the lighting makes an interesting backdrop, it does nothing for enhancing the subject. And the focus could have been sharper.</td>', 'The scene could have been composed better. Maybe brought the subject down to the bottom third of the image, where it would have been placed stronger. Also, although the lighting makes an interesting backdrop, it does nothing for enhancing the subject. And the focus could have been sharper.', '2007-01-27 04:46:30.000000', NULL, 1),
(3290054, 458719, 46314, '<td valign="top">Too many distracting elements here. Composition could have been simplified dramatically.</td>', 'Too many distracting elements here. Composition could have been simplified dramatically.', '2007-01-27 04:47:28.000000', NULL, 1),
(3290055, 455672, 46314, '<td valign="top">Nice control of your lighting. Would make a good desktop background.</td>', 'Nice control of your lighting. Would make a good desktop background.', '2007-01-27 04:47:55.000000', NULL, 1),
(3290056, 458643, 46314, '<td valign="top">Looks a little too compressed into that left hand corner. Could maybe have placed it on the spot where the left third and bottom third intersect to make the composition stronger. Ligthing and focus are good though.</td>', 'Looks a little too compressed into that left hand corner. Could maybe have placed it on the spot where the left third and bottom third intersect to make the composition stronger. Ligthing and focus are good though.', '2007-01-27 04:49:20.000000', NULL, 1),
(3290059, 457117, 46314, '<td valign="top">Nice control of your lighting. And the subject is composed very well. And unlike most of the ''small object on a white background shots'', I think the bite out of the cookie and the little scattered crumbs add interest to the subject, and make it a more enjoyable photo. Well done.</td>', 'Nice control of your lighting. And the subject is composed very well. And unlike most of the ''small object on a white background shots'', I think the bite out of the cookie and the little scattered crumbs add interest to the subject, and make it a more enjoyable photo. Well done.', '2007-01-27 04:51:06.000000', NULL, 1),
(3290061, 455362, 46314, '<td valign="top">I''m not quite sure about the minimalism aspect, but regardless of that, the composition is poor and the lighting is quite bad.</td>', 'I''m not quite sure about the minimalism aspect, but regardless of that, the composition is poor and the lighting is quite bad.', '2007-01-27 04:52:36.000000', NULL, 1),
(3290063, 456821, 46314, '<td valign="top">A very neat shot. But I think it could have been made more interesting by making the lighting on the bullets a bit more dramatic (maybe more highlights, or more shadow - to add a bit of depth). Also, I wonder if correcting the white balance so that the background was pure white rather than cream might have made the subject jump out a bit more?</td>', 'A very neat shot. But I think it could have been made more interesting by making the lighting on the bullets a bit more dramatic (maybe more highlights, or more shadow - to add a bit of depth). Also, I wonder if correcting the white balance so that the background was pure white rather than cream might have made the subject jump out a bit more?', '2007-01-27 04:56:06.000000', NULL, 1),
(3290065, 455688, 46314, '<td valign="top">Nice shot. I like the way the bright red chilli jumps out at you from that dark backround. The highlights on the chilli are perhaps a bit harsh, but overall the lighting is good. Composition is not quite perfect - the smoke seems to be bunched up in the corner (but I can imagine how hard it must have been to capture it perfectly). Good work.</td>', 'Nice shot. I like the way the bright red chilli jumps out at you from that dark backround. The highlights on the chilli are perhaps a bit harsh, but overall the lighting is good. Composition is not quite perfect - the smoke seems to be bunched up in the corner (but I can imagine how hard it must have been to capture it perfectly). Good work.', '2007-01-27 04:58:08.000000', NULL, 1),
(3290066, 457224, 46314, '<td valign="top">I love the minimalism in this one. The lighting control was excellent, and the composition is perfect. Very well done.</td>', 'I love the minimalism in this one. The lighting control was excellent, and the composition is perfect. Very well done.', '2007-01-27 04:58:51.000000', NULL, 1),
(3290068, 458653, 46314, '<td valign="top">Not quite stylised enough to pull of the ''small object on a white background'' shot well enough. Maybe a very shallow DOF, or more dramatic contrast lighting would have made it stick out a bit more.<br/>Also, it would have helped if the white balance had been set to make the background more white, I think.</td>', 'Not quite stylised enough to pull of the ''small object on a white background'' shot well enough. Maybe a very shallow DOF, or more dramatic contrast lighting would have made it stick out a bit more.Also, it would have helped if the white balance had been set to make the background more white, I think.', '2007-01-27 05:00:56.000000', NULL, 1),
(3290069, 456404, 46314, '<td valign="top">Clever. Handled the lighting very well. Very well executed.</td>', 'Clever. Handled the lighting very well. Very well executed.', '2007-01-27 05:01:51.000000', NULL, 1),
(3290070, 456303, 46314, '<td valign="top">The lighting is not great. Sky is completely blown out with a bit of lens flare, and all of the texture of the rocks is lost in the shadows. Composition could have been simplified too, by leaving out the left third of the image.</td>', 'The lighting is not great. Sky is completely blown out with a bit of lens flare, and all of the texture of the rocks is lost in the shadows. Composition could have been simplified too, by leaving out the left third of the image.', '2007-01-27 05:03:33.000000', NULL, 1),
(3290071, 457871, 46314, '<td valign="top">I like the spot of red amongst the subdued colours, but I think overall th branches on the right are a bit too distracting.</td>', 'I like the spot of red amongst the subdued colours, but I think overall th branches on the right are a bit too distracting.', '2007-01-27 05:05:11.000000', NULL, 1),
(3290072, 455902, 46314, '<td valign="top">Nice rhythm in the image, and the spire is well emphasised. Will look even better after the challenge when you can edit it to bump up the contrast.</td>', 'Nice rhythm in the image, and the spire is well emphasised. Will look even better after the challenge when you can edit it to bump up the contrast.', '2007-01-27 05:06:10.000000', NULL, 1),
(3290073, 457057, 46314, '<td valign="top">Not interesting enough. Even though it''s minimalist and abstract, there still has to be something to make the viewer want to look at it.</td>', 'Not interesting enough. Even though it''s minimalist and abstract, there still has to be something to make the viewer want to look at it.', '2007-01-27 05:06:54.000000', NULL, 1),
(3290074, 455773, 46314, '<td valign="top">Awesome lighting and DOF. Sharpness is very good, and the colours are fabulous. Nice shot.</td>', 'Awesome lighting and DOF. Sharpness is very good, and the colours are fabulous. Nice shot.', '2007-01-27 05:07:52.000000', NULL, 1),
(3290075, 458298, 46314, '<td valign="top">Um, I like what you were going for here. This type of shot is usually my favourite: just a narrow band of land, and an awesome sky. But unfortunately here, you didn''t really include a subject. The farm houses are just too small to make out, and so it doesn''t leave much for the viewer to look at.</td>', 'Um, I like what you were going for here. This type of shot is usually my favourite: just a narrow band of land, and an awesome sky. But unfortunately here, you didn''t really include a subject. The farm houses are just too small to make out, and so it doesn''t leave much for the viewer to look at.', '2007-01-27 05:09:27.000000', NULL, 1),
(3290076, 458718, 46314, '<td valign="top">Quite zen, including the title (which has a haiku feel).</td>', 'Quite zen, including the title (which has a haiku feel).', '2007-01-27 05:10:08.000000', NULL, 1),
(3290077, 458280, 46314, '<td valign="top">Very minimalist. Interesting lighting.</td>', 'Very minimalist. Interesting lighting.', '2007-01-27 05:10:59.000000', NULL, 1),
(3290078, 458695, 46314, '<td valign="top">Nice focus and DOF. Colours are very interesting. Maybe could have cropped the composition a bit to add to the minimalist feel.</td>', 'Nice focus and DOF. Colours are very interesting. Maybe could have cropped the composition a bit to add to the minimalist feel.', '2007-01-27 05:12:02.000000', NULL, 1),
(3290081, 456926, 46314, '<td valign="top">Not a great photo. The central composition isn''t very strong, and you can hardly make out any details of the subject.</td>', 'Not a great photo. The central composition isn''t very strong, and you can hardly make out any details of the subject.', '2007-01-27 05:17:02.000000', NULL, 1),
(3290085, 457686, 46314, '<td valign="top">Nice idea for the minimalism challenge. Somehow I don''t think it was executed perfectly. Would have liked to have seen the feet more ''posed'', using them to the fullest advantage to explore the interplay between the light and shadows. The bottom left is just too dark - it throws off the balance of the image.</td>', 'Nice idea for the minimalism challenge. Somehow I don''t think it was executed perfectly. Would have liked to have seen the feet more ''posed'', using them to the fullest advantage to explore the interplay between the light and shadows. The bottom left is just too dark - it throws off the balance of the image.', '2007-01-27 05:20:25.000000', NULL, 1),
(3290086, 456192, 46314, '<td valign="top">All that stuff going on in the background on the left is distracting. Could have simplified the composition a bit by going for a tighter crop.</td>', 'All that stuff going on in the background on the left is distracting. Could have simplified the composition a bit by going for a tighter crop.', '2007-01-27 05:21:39.000000', NULL, 1),
(3290087, 458727, 46314, '<td valign="top">Very interesting colours.</td>', 'Very interesting colours.', '2007-01-27 05:22:30.000000', NULL, 1),
(3290088, 456205, 46314, '<td valign="top">Funny idea. A more overhead angle might have allowed for more detail on the food arrangement.</td>', 'Funny idea. A more overhead angle might have allowed for more detail on the food arrangement.', '2007-01-27 05:23:51.000000', NULL, 1),
(3290089, 458606, 46314, '<td valign="top">Very nice shot. I like how the colours of the shirt compliment the backgroud. Not really sure about the minimalist element, but it certainly is a simple composition.</td>', 'Very nice shot. I like how the colours of the shirt compliment the backgroud. Not really sure about the minimalist element, but it certainly is a simple composition.', '2007-01-27 05:25:05.000000', NULL, 1),
(3290090, 456131, 46314, '<td valign="top">A brighter background might have allowed the sphere to stand out more. Right now the lighting just feels a bit murky.</td>', 'A brighter background might have allowed the sphere to stand out more. Right now the lighting just feels a bit murky.', '2007-01-27 05:26:08.000000', NULL, 1),
(3290091, 458083, 46314, '<td valign="top">Not as interesting as the whole building.</td>', 'Not as interesting as the whole building.', '2007-01-27 05:26:45.000000', NULL, 1),
(3290093, 455393, 46314, '<td valign="top">Pity the perspective of the lens distorts the tiles a bit so that the ones on the left don''t look as vertical as the ones on the right (or maybe that''s just because of faulty building contractors :-) ). Anyway, that''s minor, because this is a great shot. Minimalist indeed. And the subject is interesting (unlike many of the ''small object on a white background'' shots). Very well done. Focus, sharpness and DOF are good, composition is good. And lighting is very nicely controlled. One of my favourites of this challenge.</td>', 'Pity the perspective of the lens distorts the tiles a bit so that the ones on the left don''t look as vertical as the ones on the right (or maybe that''s just because of faulty building contractors :-) ). Anyway, that''s minor, because this is a great shot. Minimalist indeed. And the subject is interesting (unlike many of the ''small object on a white background'' shots). Very well done. Focus, sharpness and DOF are good, composition is good. And lighting is very nicely controlled. One of my favourites of this challenge.', '2007-01-27 05:31:40.000000', NULL, 1),
(3290094, 457507, 46314, '<td valign="top">Needed better focusing. Subject is fuzzy...</td>', 'Needed better focusing. Subject is fuzzy...', '2007-01-27 05:32:09.000000', NULL, 1),
(3290095, 456987, 46314, '<td valign="top">Nicely composed, good use of colour. Well executed.</td>', 'Nicely composed, good use of colour. Well executed.', '2007-01-27 05:32:42.000000', NULL, 1),
(3290096, 455467, 46314, '<td valign="top">Great photo. Lighting is excellently controlled. The tonal range is excellent too. DOF and sharpness is good. And you have a funny looking dog. Well done.</td>', 'Great photo. Lighting is excellently controlled. The tonal range is excellent too. DOF and sharpness is good. And you have a funny looking dog. Well done.', '2007-01-27 05:33:48.000000', NULL, 1),
(3290099, 458509, 46314, '<td valign="top">Well composed, and use of colour is good.</td>', 'Well composed, and use of colour is good.', '2007-01-27 05:34:30.000000', NULL, 1),
(3290101, 458640, 46314, '<td valign="top">Lighting could have been better controlled - shadows on the left are distracting.</td>', 'Lighting could have been better controlled - shadows on the left are distracting.', '2007-01-27 05:35:44.000000', NULL, 1),
(3290103, 455309, 46314, '<td valign="top">Not quite interesting enough. But not badly executed.</td>', 'Not quite interesting enough. But not badly executed.', '2007-01-27 05:36:58.000000', NULL, 1),
(3290104, 458508, 46314, '<td valign="top">Bizarre.Could have used more light on the subject.</td>', 'Bizarre.Could have used more light on the subject.', '2007-01-27 05:37:34.000000', NULL, 1),
(3290106, 455705, 46314, '<td valign="top">Needed something to make this subject more dramatic and interesting. Could have tried standing the crayon straight up, and maybe getting a shadow off it?</td>', 'Needed something to make this subject more dramatic and interesting. Could have tried standing the crayon straight up, and maybe getting a shadow off it?', '2007-01-27 05:38:55.000000', NULL, 1),
(3290107, 458655, 46314, '<td valign="top">I don''t get the minimalism.</td>', 'I don''t get the minimalism.', '2007-01-27 05:39:44.000000', NULL, 1),
(3290109, 457961, 46314, '<td valign="top">I presume the small deer is your ''minimalist'' subject. Unfortunately it gets too lost in the busy background to really stick out.</td>', 'I presume the small deer is your ''minimalist'' subject. Unfortunately it gets too lost in the busy background to really stick out.', '2007-01-27 05:41:47.000000', NULL, 1),
(3290110, 456846, 46314, '<td valign="top">It''s minimalist all right, but lacks any interest.</td>', 'It''s minimalist all right, but lacks any interest.', '2007-01-27 05:42:28.000000', NULL, 1),
(3290112, 455663, 46314, '<td valign="top">Nice bands of texture running across the image, separating it into thirds: good composition. The sun itself is a bit blown out though - maybe it would have been better if you''d left it out of the photo (ie. leave off the top third)? You''d still have it''s bright reflecting in the water for interest.</td>', 'Nice bands of texture running across the image, separating it into thirds: good composition. The sun itself is a bit blown out though - maybe it would have been better if you''d left it out of the photo (ie. leave off the top third)? You''d still have it''s bright reflecting in the water for interest.', '2007-01-27 05:45:14.000000', NULL, 1),
(3290113, 457962, 46314, '<td valign="top">Lighting needs work, background is distracting.</td>', 'Lighting needs work, background is distracting.', '2007-01-27 05:45:45.000000', NULL, 1),
(3290114, 458801, 46314, '<td valign="top">Nothing dramatically compelling in this image.</td>', 'Nothing dramatically compelling in this image.', '2007-01-27 05:46:35.000000', NULL, 1),
(3290115, 455768, 46314, '<td valign="top">Nice silhouette.</td>', 'Nice silhouette.', '2007-01-27 05:47:03.000000', NULL, 1),
(3290131, 458743, 46314, '<td valign="top">It''s distracting that the coffee cup is tilted, and the lighting needed to be better. Also, white balance could have made the cup contrast better against the black.</td>', 'It''s distracting that the coffee cup is tilted, and the lighting needed to be better. Also, white balance could have made the cup contrast better against the black.', '2007-01-27 06:13:15.000000', NULL, 1),
(3290135, 457667, 46314, '<td valign="top">Nice idea for minimalism. I like the almost duotone effect. The composition could have been improved more. The subject gets a bit lost in the whole image.</td>', 'Nice idea for minimalism. I like the almost duotone effect. The composition could have been improved more. The subject gets a bit lost in the whole image.', '2007-01-27 06:14:02.000000', NULL, 1),
(3290139, 456258, 46314, '<td valign="top">Not sure if this fits the minimalist theme, but regardless of that, this isn''t a great shot. The central composition isn''t very strong, and the firetruck? sticking out on the right is distracting. Also the fireman in the background, half blocked by the one in the foreground looks odd.</td>', 'Not sure if this fits the minimalist theme, but regardless of that, this isn''t a great shot. The central composition isn''t very strong, and the firetruck? sticking out on the right is distracting. Also the fireman in the background, half blocked by the one in the foreground looks odd.', '2007-01-27 06:15:49.000000', NULL, 1),
(3290143, 456970, 46314, '<td valign="top">Nice use of black and white. Excellent lighting and use of it. This would have been a doddle to do in Photoshop, but achieving such good contrast at execution is superb. Composition could be a bit more simplified.</td>', 'Nice use of black and white. Excellent lighting and use of it. This would have been a doddle to do in Photoshop, but achieving such good contrast at execution is superb. Composition could be a bit more simplified.', '2007-01-27 06:17:30.000000', NULL, 1),
(3290144, 458738, 46314, '<td valign="top">Ligthing seems a bit dull - not enough contrast maybe?</td>', 'Ligthing seems a bit dull - not enough contrast maybe?', '2007-01-27 06:18:09.000000', NULL, 1),
(3290145, 455834, 46314, '<td valign="top">Interesting idea. Certainly a more original entry.</td>', 'Interesting idea. Certainly a more original entry.', '2007-01-27 06:18:42.000000', NULL, 1),
(3290150, 458799, 46314, '<td valign="top">I think there''s too much foreground. Seems to detract a bit from the subject and the strong line of the horizon, and it contains many distracting elements. Good use of hyperfocal distance though.</td>', 'I think there''s too much foreground. Seems to detract a bit from the subject and the strong line of the horizon, and it contains many distracting elements. Good use of hyperfocal distance though.', '2007-01-27 06:19:59.000000', NULL, 1),
(3290153, 458036, 46314, '<td valign="top">I like this shot. The side-lighting makes the subject more interesting, and I like the muted blue colour of the backround. The lens flare? on the left does distract a bit though.</td>', 'I like this shot. The side-lighting makes the subject more interesting, and I like the muted blue colour of the backround. The lens flare? on the left does distract a bit though.', '2007-01-27 06:21:41.000000', NULL, 1),
(3290158, 457729, 46314, '<td valign="top">Great close up. The line leading up to the pen really draws the eye and creates a nice rhythm. The DOF is superb - really highlights the subject, but doesn''t throw away the rest of the image. One of the best of this challenge, well done.</td>', 'Great close up. The line leading up to the pen really draws the eye and creates a nice rhythm. The DOF is superb - really highlights the subject, but doesn''t throw away the rest of the image. One of the best of this challenge, well done.', '2007-01-27 06:23:33.000000', NULL, 1),
(3290159, 458452, 46314, '<td valign="top">Nice repeating colours, lines and tones. Top left spoils it a bit, but overall an interesting minimalist shot.</td>', 'Nice repeating colours, lines and tones. Top left spoils it a bit, but overall an interesting minimalist shot.', '2007-01-27 06:24:18.000000', NULL, 1),
(3290160, 458216, 46314, '<td valign="top">Lighting is flat - leaves the subject dull and uninteresting.</td>', 'Lighting is flat - leaves the subject dull and uninteresting.', '2007-01-27 06:24:41.000000', NULL, 1),
(3290161, 458045, 46314, '<td valign="top">Even though it''s minimalism, I''d still like to have a subject to be able to study. The ships are just too dark and small here - the specks of light are uninteresting.</td>', 'Even though it''s minimalism, I''d still like to have a subject to be able to study. The ships are just too dark and small here - the specks of light are uninteresting.', '2007-01-27 06:25:35.000000', NULL, 1),
(3290163, 458835, 46314, '<td valign="top">That dark branch in the back spoils the composition a bit, as well as the minimalism. Still, good focus and DOF and nice lighting.</td>', 'That dark branch in the back spoils the composition a bit, as well as the minimalism. Still, good focus and DOF and nice lighting.', '2007-01-27 06:26:16.000000', NULL, 1),
