INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3291435, 458743, 69387, '<td valign="top">This is a great idea. What would have worked better for this shot is to get a brighter/whiter mug to make it stand out more. Good luck, this should do you well.</td>', 'This is a great idea. What would have worked better for this shot is to get a brighter/whiter mug to make it stand out more. Good luck, this should do you well.', '2007-01-27 16:07:07.000000', NULL, 1),
