(3293366, 457878, 28029, '<td valign="top">Perfect for the challenge. Beautiful coloration and composition. 10</td>', 'Perfect for the challenge. Beautiful coloration and composition. 10', '2007-01-28 09:44:22.000000', NULL, 1),
(3293536, 458740, 60899, '<td valign="top">Awesome...hope to see this in top 5...10</td>', 'Awesome...hope to see this in top 5...10', '2007-01-28 10:59:17.000000', NULL, 1),
(3293674, 458695, 15711, '<td valign="top">I think this is beautiful and I like the bokeh, but it doesn''t speak minimal to me.  If maybe it were a single flower off in the distance of small in the corner, or perhaps the butterfly as a single subject in the shot, it would have met the challenge more for me.</td>', 'I think this is beautiful and I like the bokeh, but it doesn''t speak minimal to me.  If maybe it were a single flower off in the distance of small in the corner, or perhaps the butterfly as a single subject in the shot, it would have met the challenge more for me.', '2007-01-28 12:12:56.000000', NULL, 1),
(3293675, 458771, 15711, '<td valign="top">I like the idea of this.  I think to really be "minimal" to me, there would be more negative space and perhaps you''d pan back so that the heart was smaller.  Maybe only one fish too, but that''s just me.</td>', 'I like the idea of this.  I think to really be "minimal" to me, there would be more negative space and perhaps you''d pan back so that the heart was smaller.  Maybe only one fish too, but that''s just me.', '2007-01-28 12:13:44.000000', NULL, 1),
(3293677, 457409, 15711, '<td valign="top">I like the idea of this but the trees kind of kill the minimalism for me.  Maybe I''m taking the definition too literally.</td>', 'I like the idea of this but the trees kind of kill the minimalism for me.  Maybe I''m taking the definition too literally.', '2007-01-28 12:14:51.000000', NULL, 1),
(3293679, 455672, 15711, '<td valign="top">I love this image.  It suits the challenge perfectly.  The leaf stands out amidst all of the white.  You left the shadow, which is good, so that it doesn''t appear to just be floating in space. 8</td>', 'I love this image.  It suits the challenge perfectly.  The leaf stands out amidst all of the white.  You left the shadow, which is good, so that it doesn''t appear to just be floating in space. 8', '2007-01-28 12:15:41.000000', NULL, 1),
(3293681, 457891, 15711, '<td valign="top">I like the idea of this very much.  I think I would have panned back and even made the slippers smaller in the shot.</td>', 'I like the idea of this very much.  I think I would have panned back and even made the slippers smaller in the shot.', '2007-01-28 12:16:21.000000', NULL, 1),
(3293684, 458818, 15711, '<td valign="top">I like the long shadow.  It certainly suits the challenge.  I wonder if it has enough POW to wow the voters. 7</td>', 'I like the long shadow.  It certainly suits the challenge.  I wonder if it has enough POW to wow the voters. 7', '2007-01-28 12:17:43.000000', NULL, 1),
(3293742, 457845, 60899, '<td valign="top">Oh ho ho.....a very innovative picture....jus hope ppl dont miss the ?....8</td>', 'Oh ho ho.....a very innovative picture....jus hope ppl dont miss the ?....8', '2007-01-28 13:01:42.000000', NULL, 1),
(3293747, 458342, 15266, '<td valign="top">I do lke the light and the rock formation in the composition, the moodiness of the still water and heavy clouds is nice too.  Only nit is the crooked horizon.  :/</td>', 'I do lke the light and the rock formation in the composition, the moodiness of the still water and heavy clouds is nice too.  Only nit is the crooked horizon.  :/', '2007-01-28 13:05:16.000000', NULL, 1),
