(3294319, 458659, 8139, '<td valign="top">Not so minimalistic than that, but clever idea and execution. Nice !</td>', 'Not so minimalistic than that, but clever idea and execution. Nice !', '2007-01-28 17:08:11.000000', NULL, 1),
