(3294605, 455661, 31341, '<td valign="top">I don''t put this in the minimalism catagory.</td>', 'I don''t put this in the minimalism catagory.', '2007-01-28 18:32:00.000000', NULL, 1),
(3294610, 455362, 31341, '<td valign="top">I am missing the minimalism part of this.</td>', 'I am missing the minimalism part of this.', '2007-01-28 18:32:48.000000', NULL, 1),
(3294616, 456397, 31341, '<td valign="top">I don''t classify this as minimalistic.</td>', 'I don''t classify this as minimalistic.', '2007-01-28 18:33:53.000000', NULL, 1),
