(3298969, 458711, 69387, '<td valign="top">Cute, a solid 7!</td>', 'Cute, a solid 7!', '2007-01-29 14:02:08.000000', NULL, 1),
(3298973, 458643, 69387, '<td valign="top">Lovely flower, meets the challenge. A solid 7 for you!</td>', 'Lovely flower, meets the challenge. A solid 7 for you!', '2007-01-29 14:02:26.000000', NULL, 1),
(3299265, 458166, 57045, '<td valign="top">Nice dept of field</td>', 'Nice dept of field', '2007-01-29 15:01:11.000000', NULL, 1),
(3299274, 458643, 30982, '<td valign="top">Nice work with the light, especially with no editing, to get a perfeclty black background and good light on your subject.</td>', 'Nice work with the light, especially with no editing, to get a perfeclty black background and good light on your subject.', '2007-01-29 15:02:45.000000', NULL, 1),
(3299287, 458603, 30982, '<td valign="top">Very good out of camera sharpness, color, and white background.</td>', 'Very good out of camera sharpness, color, and white background.', '2007-01-29 15:04:50.000000', NULL, 1),
(3299301, 455927, 24913, '<td valign="top">YES, that is a very wierd place to have a hinge :)</td>', 'YES, that is a very wierd place to have a hinge :)', '2007-01-29 15:09:13.000000', NULL, 1),
(3299305, 458587, 24913, '<td valign="top">I find the shadow a bit distracting.</td>', 'I find the shadow a bit distracting.', '2007-01-29 15:09:55.000000', NULL, 1),
(3299311, 457574, 24913, '<td valign="top">WOW! That must have taken a long time to get that that way.... nice idea.</td>', 'WOW! That must have taken a long time to get that that way.... nice idea.', '2007-01-29 15:11:45.000000', NULL, 1),
(3300096, 457952, 58610, '<td valign="top">A really good idea. A <i>little</i> more ambient light to increase the details a little would be good.</td>', 'A really good idea. A little more ambient light to increase the details a little would be good.', '2007-01-29 18:16:35.000000', NULL, 1),
(3300097, 458338, 58610, '<td valign="top">Very nice composition and lighting.</td>', 'Very nice composition and lighting.', '2007-01-29 18:17:31.000000', NULL, 1),
(3300102, 457490, 58610, '<td valign="top">Going out of the edge: I like that. The desat keeps it very simple and clean.</td>', 'Going out of the edge: I like that. The desat keeps it very simple and clean.', '2007-01-29 18:19:06.000000', NULL, 1),
(3300103, 456192, 69537, '<td valign="top">I like this one.</td>', 'I like this one.', '2007-01-29 18:19:23.000000', NULL, 1),
(3300110, 455377, 58610, '<td valign="top">Really nice shot. The shallow dof really makes this work. The falling snow is a great detail. Good job.</td>', 'Really nice shot. The shallow dof really makes this work. The falling snow is a great detail. Good job.', '2007-01-29 18:20:47.000000', NULL, 1),
(3300124, 456084, 58610, '<td valign="top">Very inspiring for a Minimal Editing challenge. Can''t wait to find out how you did it.</td>', 'Very inspiring for a Minimal Editing challenge. Can''t wait to find out how you did it.', '2007-01-29 18:24:09.000000', NULL, 1),
(3300135, 458587, 58610, '<td valign="top">I would prefer lighting that highlighted the table rather than the wall (the table is more interesting), but the shadow effect is nice. Could be a little sharper.</td>', 'I would prefer lighting that highlighted the table rather than the wall (the table is more interesting), but the shadow effect is nice. Could be a little sharper.', '2007-01-29 18:28:03.000000', NULL, 1),
(3300141, 457425, 58610, '<td valign="top">Not really sharp, and you have more than one subject which detracts from the composition.</td>', 'Not really sharp, and you have more than one subject which detracts from the composition.', '2007-01-29 18:30:02.000000', NULL, 1),
(3300148, 458298, 58610, '<td valign="top">Reminds me of the Windows logo a little bit (not meant as an insult). I like the way you''ve treated the ground as a small portion of the landscape. Very successful.</td>', 'Reminds me of the Windows logo a little bit (not meant as an insult). I like the way you''ve treated the ground as a small portion of the landscape. Very successful.', '2007-01-29 18:32:14.000000', NULL, 1),
(3300154, 455688, 58610, '<td valign="top">Cool! or not. I guess <i>smokin''</i> would be more appropriate. NIce job in any case. Good lighting and composition. Great setup. Howdja doit?</td>', 'Cool! or not. I guess smokin'' would be more appropriate. NIce job in any case. Good lighting and composition. Great setup. Howdja doit?', '2007-01-29 18:34:16.000000', NULL, 1),
(3300159, 456205, 58610, '<td valign="top">That took a minute to sink in. Nicely done.</td>', 'That took a minute to sink in. Nicely done.', '2007-01-29 18:35:14.000000', NULL, 1),
(3300163, 456214, 58610, '<td valign="top">This would be even better had you place the structure a little off centered. Perhaps there were obstacles you were avoinding.</td>', 'This would be even better had you place the structure a little off centered. Perhaps there were obstacles you were avoinding.', '2007-01-29 18:36:24.000000', NULL, 1),
(3300218, 458676, 60073, '<td valign="top">such a cute dog</td>', 'such a cute dog', '2007-01-29 18:51:43.000000', NULL, 1),
(3300697, 458771, 60846, '<td valign="top">gooooooooooooooooooooooood</td>', 'gooooooooooooooooooooooood', '2007-01-29 21:09:44.000000', NULL, 1),
(3301725, 458082, 60899, '<td valign="top">Excellent Contrast and clarity...9</td>', 'Excellent Contrast and clarity...9', '2007-01-30 02:21:57.000000', NULL, 1),
(3301798, 458740, 56400, '<td valign="top">The horizon could have been straighter but, still a real nice shot</td>', 'The horizon could have been straighter but, still a real nice shot', '2007-01-30 03:12:40.000000', NULL, 1),
(3301806, 458225, 56400, '<td valign="top">Normally a centered subject is frowned upon but the centered heart works here with the arc of the necklace giving a good dynamic element and just the hint of the neck giving the perspective. Nice job.</td>', 'Normally a centered subject is frowned upon but the centered heart works here with the arc of the necklace giving a good dynamic element and just the hint of the neck giving the perspective. Nice job.', '2007-01-30 03:19:05.000000', NULL, 1),
(3301815, 456397, 60899, '<td valign="top">Lovely snap .... but i feel it goes a bit against the theme</td>', 'Lovely snap .... but i feel it goes a bit against the theme', '2007-01-30 03:27:27.000000', NULL, 1),
(3301877, 457681, 56400, '<td valign="top">Despite the title, I think most people are going to see that curtain of ice as your main subject and that takes up too much real estate to be considered minimal.</td>', 'Despite the title, I think most people are going to see that curtain of ice as your main subject and that takes up too much real estate to be considered minimal.', '2007-01-30 04:08:28.000000', NULL, 1),
(3301888, 457117, 56400, '<td valign="top">The crumbs are a good addition and a few more wouldn''t have hurt either. (This also gave me a good case of the munchies.)</td>', 'The crumbs are a good addition and a few more wouldn''t have hurt either. (This also gave me a good case of the munchies.)', '2007-01-30 04:20:55.000000', NULL, 1),
(3301901, 458702, 56400, '<td valign="top">Not very still looking and it takes up too much of the frame anyway.</td>', 'Not very still looking and it takes up too much of the frame anyway.', '2007-01-30 04:28:34.000000', NULL, 1),
(3301911, 455393, 56400, '<td valign="top">Someone could be in for maximal doo-doo with this oversight :-). Good shot and humor.</td>', 'Someone could be in for maximal doo-doo with this oversight :-). Good shot and humor.', '2007-01-30 04:33:38.000000', NULL, 1),
(3301923, 458180, 56400, '<td valign="top">Somehow this doesn''t look right without the stem. If it is floating in water, there should be some kind of indication of it and I don''t see it. Right now it just looks like it is floating in air with no support.</td>', 'Somehow this doesn''t look right without the stem. If it is floating in water, there should be some kind of indication of it and I don''t see it. Right now it just looks like it is floating in air with no support.', '2007-01-30 04:39:19.000000', NULL, 1),
(3301926, 458400, 56400, '<td valign="top">Nice texture to the BG without being overpowering.</td>', 'Nice texture to the BG without being overpowering.', '2007-01-30 04:42:43.000000', NULL, 1),
(3301936, 457490, 56400, '<td valign="top">The curve of the bottle would have added a nice dynamic element to the shot IF the WHOLE bottle could have been seen. It is unfortunate that it was cut off.</td>', 'The curve of the bottle would have added a nice dynamic element to the shot IF the WHOLE bottle could have been seen. It is unfortunate that it was cut off.', '2007-01-30 04:48:32.000000', NULL, 1),
(3301954, 456284, 56400, '<td valign="top">This might be very minimal but, there still needs to be some frame of reference as to where these twigs fit into the world. Right now they just look like they are floating in air.</td>', 'This might be very minimal but, there still needs to be some frame of reference as to where these twigs fit into the world. Right now they just look like they are floating in air.', '2007-01-30 05:03:25.000000', NULL, 1),
(3302336, 455362, 70270, '<td valign="top">the rookster strikes again?  Minimal effort gets you a 10.</td>', 'the rookster strikes again?  Minimal effort gets you a 10.', '2007-01-30 08:57:40.000000', NULL, 1),
(3302362, 458266, 73019, '<td valign="top">I like it</td>', 'I like it', '2007-01-30 09:08:38.000000', NULL, 1),
(3302431, 456268, 72349, '<td valign="top">Evokes the feeling of being on a long journey.</td>', 'Evokes the feeling of being on a long journey.', '2007-01-30 09:38:23.000000', NULL, 1),
(3302502, 455859, 65592, '<td valign="top">Try to avoid centering the subject and respect the rule of thirds an you will achieve a better result IMO. Original picture.</td>', 'Try to avoid centering the subject and respect the rule of thirds an you will achieve a better result IMO. Original picture.', '2007-01-30 10:14:40.000000', NULL, 1),
(3302507, 455393, 65592, '<td valign="top">Ha,ha,ha...</td>', 'Ha,ha,ha...', '2007-01-30 10:16:18.000000', NULL, 1),
(3302512, 455888, 65592, '<td valign="top">Too much info in this photograph to be considered "minimalistic". On the other hand it is a very nice capture.</td>', 'Too much info in this photograph to be considered "minimalistic". On the other hand it is a very nice capture.', '2007-01-30 10:17:45.000000', NULL, 1),
(3302517, 458653, 65592, '<td valign="top">The shadow cast by the nuts is a little disturbing to me. Well de-centered subject.</td>', 'The shadow cast by the nuts is a little disturbing to me. Well de-centered subject.', '2007-01-30 10:19:32.000000', NULL, 1),
(3302531, 458280, 65592, '<td valign="top">i like very much your idea, the black background enhances strongly the subject but it is located in the extreme border of the photograph...too much IMO. It is a good idea to work with.</td>', 'i like very much your idea, the black background enhances strongly the subject but it is located in the extreme border of the photograph...too much IMO. It is a good idea to work with.', '2007-01-30 10:24:44.000000', NULL, 1),
(3302538, 456302, 65592, '<td valign="top">I do not know what i am looking at, but surprisigly i like it ¿? Very strange at all.</td>', 'I do not know what i am looking at, but surprisigly i like it ¿? Very strange at all.', '2007-01-30 10:28:00.000000', NULL, 1),
(3302540, 456890, 65592, '<td valign="top">Very nice capture.</td>', 'Very nice capture.', '2007-01-30 10:29:05.000000', NULL, 1),
(3302555, 457878, 65592, '<td valign="top">Nice capture. I love those colors.</td>', 'Nice capture. I love those colors.', '2007-01-30 10:36:00.000000', NULL, 1),
(3302591, 458370, 47096, '<td valign="top">I like the idea. Would have liked the result better if the light source wasn''t in the photo. I think it distracts from the main subject.</td>', 'I like the idea. Would have liked the result better if the light source wasn''t in the photo. I think it distracts from the main subject.', '2007-01-30 10:54:20.000000', NULL, 1),
(3302747, 456227, 42495, '<td valign="top">Great job meeting the challenge, and the minimal postprocessing adds to the effect.</td>', 'Great job meeting the challenge, and the minimal postprocessing adds to the effect.', '2007-01-30 11:58:26.000000', NULL, 1),
(3302923, 458705, 24913, '<td valign="top">Very intersting technique/idea.</td>', 'Very intersting technique/idea.', '2007-01-30 12:48:13.000000', NULL, 1),
(3303112, 457591, 45519, '<td valign="top">Great use of light/shadow to make for a more dramatic and dynmic minimilist shot.  Nice texture and color as well.</td>', 'Great use of light/shadow to make for a more dramatic and dynmic minimilist shot.  Nice texture and color as well.', '2007-01-30 13:12:33.000000', NULL, 1),
(3303138, 457878, 24913, '<td valign="top">so delicate....</td>', 'so delicate....', '2007-01-30 13:16:32.000000', NULL, 1),
(3303147, 458721, 45519, '<td valign="top">The white push pins aren''t exactly the right height and some don''t appear to be pushed in perfectly straight!  &lt;-- DPC perfectionist humor (kidding of course).  Nicely done. :)</td>', 'The white push pins aren''t exactly the right height and some don''t appear to be pushed in perfectly straight!  <-- DPC perfectionist humor (kidding of course).  Nicely done. :)', '2007-01-30 13:18:31.000000', NULL, 1),
(3303166, 455877, 45519, '<td valign="top">Excellent ... great light and texture, love the contrast between the red flowers (subject) and background.  One of the few true standouts so far.</td>', 'Excellent ... great light and texture, love the contrast between the red flowers (subject) and background.  One of the few true standouts so far.', '2007-01-30 13:23:26.000000', NULL, 1),
(3303183, 457490, 45519, '<td valign="top">Odd compositional choice.  The bottle fully in frame would have made for a nice, simple minimilistic image on it''s own ... not sure being cut off does anything to help.</td>', 'Odd compositional choice.  The bottle fully in frame would have made for a nice, simple minimilistic image on it''s own ... not sure being cut off does anything to help.', '2007-01-30 13:27:37.000000', NULL, 1),
(3303193, 456114, 45519, '<td valign="top">Nice, simple scene. The water in the upper left corner keeps drawing my eye away from the primary elements -- the fence on white snow -- and is therefore a distraction, though I''d guess Minimal Editing rules are the reason this wasn''t cropped out.  Refreshing change of pace on theme interpretation compared with other entries.</td>', 'Nice, simple scene. The water in the upper left corner keeps drawing my eye away from the primary elements -- the fence on white snow -- and is therefore a distraction, though I''d guess Minimal Editing rules are the reason this wasn''t cropped out.  Refreshing change of pace on theme interpretation compared with other entries.', '2007-01-30 13:30:36.000000', NULL, 1),
(3303207, 456214, 45519, '<td valign="top">I like the idea of using something other than a red m&amp;m set against stark white poster board, and this image is well done.  I think it''s a bit of a stretch for the challenge however, with the power lines and trees and other terrestrial elements beyond "the barn."  Had this same shot been just the green-roofed structure set on a prarie or bare hillside against the sky as composed ... it''d be a winner.</td>', 'I like the idea of using something other than a red m&m set against stark white poster board, and this image is well done.  I think it''s a bit of a stretch for the challenge however, with the power lines and trees and other terrestrial elements beyond "the barn."  Had this same shot been just the green-roofed structure set on a prarie or bare hillside against the sky as composed ... it''d be a winner.', '2007-01-30 13:34:53.000000', NULL, 1),
(3303213, 455775, 45519, '<td valign="top">Better technical qualities -- exposure, contrast, etc -- and this would rate highly.  I like what''s been found (good eye) and the textures (shadow/light).</td>', 'Better technical qualities -- exposure, contrast, etc -- and this would rate highly.  I like what''s been found (good eye) and the textures (shadow/light).', '2007-01-30 13:36:23.000000', NULL, 1),
(3303216, 457032, 45519, '<td valign="top">Well done for a minimal editing challenge ... though I''ll bet you wished for even basic editing rules. :)</td>', 'Well done for a minimal editing challenge ... though I''ll bet you wished for even basic editing rules. :)', '2007-01-30 13:37:01.000000', NULL, 1),
(3303241, 458224, 45519, '<td valign="top">Is forking photography allowed on DPC?  :-P  Nicely done.</td>', 'Is forking photography allowed on DPC?  :-P  Nicely done.', '2007-01-30 13:43:07.000000', NULL, 1),
(3303252, 458727, 45519, '<td valign="top">Nicely scened/invisioned and composed ... even the tilted horizon works, adding a bit of dynanism to the shot.  I think in-camera processing might have been taken to the extreme, giving the limiting ME rules on this challenge, as saturation and sharpening are way over boosted.  Still a well capture shot with minimal elements.</td>', 'Nicely scened/invisioned and composed ... even the tilted horizon works, adding a bit of dynanism to the shot.  I think in-camera processing might have been taken to the extreme, giving the limiting ME rules on this challenge, as saturation and sharpening are way over boosted.  Still a well capture shot with minimal elements.', '2007-01-30 13:45:49.000000', NULL, 1),
(3303258, 456245, 45519, '<td valign="top">Fun interpretation and nicely captured.  Excellent exposure/light given the dynamic range created by the subject and black background, particularly with the ME rules on this challenge.  Well done.</td>', 'Fun interpretation and nicely captured.  Excellent exposure/light given the dynamic range created by the subject and black background, particularly with the ME rules on this challenge.  Well done.', '2007-01-30 13:47:59.000000', NULL, 1),
(3303309, 455642, 45519, '<td valign="top">There''s a lot going on here for minimalism, from a literal artistic standpoint.  However, the scene conveys a sense of minimalism, I suppose, in the sort of bare existence in this headstones.  Interesting subject ... would love to see it as part of another challenge with less restrictive rules (love the weathered grey headstones against rich red/orange ground cover).</td>', 'There''s a lot going on here for minimalism, from a literal artistic standpoint.  However, the scene conveys a sense of minimalism, I suppose, in the sort of bare existence in this headstones.  Interesting subject ... would love to see it as part of another challenge with less restrictive rules (love the weathered grey headstones against rich red/orange ground cover).', '2007-01-30 14:04:54.000000', NULL, 1),
(3303324, 456284, 45519, '<td valign="top">I''m guessing these are twigs poking up through water or ice? Without the title I''d have had no clue what I was looking at to be honest. With better exposure and contrast -- achievable in-camera and without less restrictive challenge guidelines -- this one could have been a contender IMO.</td>', 'I''m guessing these are twigs poking up through water or ice? Without the title I''d have had no clue what I was looking at to be honest. With better exposure and contrast -- achievable in-camera and without less restrictive challenge guidelines -- this one could have been a contender IMO.', '2007-01-30 14:08:17.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3303327, 458437, 45519, '<td valign="top">Nice lines and exposure ... love the reflection.</td>', 'Nice lines and exposure ... love the reflection.', '2007-01-30 14:08:51.000000', NULL, 1),
(3303337, 457574, 45519, '<td valign="top">A scene far from minimilism artistically speaking but of a genuinely minimalistic subject.  Nicely done.</td>', 'A scene far from minimilism artistically speaking but of a genuinely minimalistic subject.  Nicely done.', '2007-01-30 14:11:07.000000', NULL, 1),
(3303342, 456084, 45519, '<td valign="top">Illuminiating subject. ;-)  Look forward to the setup/backstory on this one.</td>', 'Illuminiating subject. ;-)  Look forward to the setup/backstory on this one.', '2007-01-30 14:12:00.000000', NULL, 1),
(3303351, 458725, 45519, '<td valign="top">Love the contrast in both color (silver on orange) and texture (smooth on thick brush stroked paint).  Makes for a cool abstract.</td>', 'Love the contrast in both color (silver on orange) and texture (smooth on thick brush stroked paint).  Makes for a cool abstract.', '2007-01-30 14:13:57.000000', NULL, 1),
(3303352, 458375, 66515, '<td valign="top">A little overexposed however I like the composition here.</td>', 'A little overexposed however I like the composition here.', '2007-01-30 14:14:00.000000', NULL, 1),
(3303356, 458719, 66515, '<td valign="top">Not really minimalism in my opinion.</td>', 'Not really minimalism in my opinion.', '2007-01-30 14:14:58.000000', NULL, 1),
(3303358, 458298, 45519, '<td valign="top">Nice choice of subject with just the right amount of non-landscape terrestrial elements.  I wish the horizon where closer to 1/3 of the lower part of the frame though.</td>', 'Nice choice of subject with just the right amount of non-landscape terrestrial elements.  I wish the horizon where closer to 1/3 of the lower part of the frame though.', '2007-01-30 14:15:59.000000', NULL, 1),
(3303361, 458643, 45519, '<td valign="top">Excellent.</td>', 'Excellent.', '2007-01-30 14:16:14.000000', NULL, 1),
(3303368, 458834, 45519, '<td valign="top">Nicely done ... excellent light and composition.  How''d you get him to sit still though? ;-)</td>', 'Nicely done ... excellent light and composition.  How''d you get him to sit still though? ;-)', '2007-01-30 14:17:15.000000', NULL, 1),
(3303372, 458400, 45519, '<td valign="top">Nice lighting and tone.  Subject isn''t terribly interesting but the textured background and shadows really help.</td>', 'Nice lighting and tone.  Subject isn''t terribly interesting but the textured background and shadows really help.', '2007-01-30 14:18:03.000000', NULL, 1),
(3303378, 458080, 45519, '<td valign="top">Striking image.  I''d swear it processed for effect if not for the challenge rules (ME) ... look forward to the backstory/description on this one.  Well done.</td>', 'Striking image.  I''d swear it processed for effect if not for the challenge rules (ME) ... look forward to the backstory/description on this one.  Well done.', '2007-01-30 14:19:18.000000', NULL, 1),
(3303383, 458081, 45519, '<td valign="top">Excellent.  Would love to see this one with proper post processing too!!!</td>', 'Excellent.  Would love to see this one with proper post processing too!!!', '2007-01-30 14:20:07.000000', NULL, 1),
(3303386, 456227, 45519, '<td valign="top">Well seen and captured ... hope to see this with proper post processing after the challenge. ;-)</td>', 'Well seen and captured ... hope to see this with proper post processing after the challenge. ;-)', '2007-01-30 14:21:08.000000', NULL, 1),
(3303401, 457430, 45519, '<td valign="top">Nice image ... though slightly different framing/composition would make this much stronger IMO.  As is, the leaves overlap the line cutting corner-to-corner diagonally, both diluting technical quality as a result.  Position the camera such that the leaves/branch were set fully against the blue sky with the bulding (?) cutting diagonally across the lower third woul really enhance the subject and visual interest.</td>', 'Nice image ... though slightly different framing/composition would make this much stronger IMO.  As is, the leaves overlap the line cutting corner-to-corner diagonally, both diluting technical quality as a result.  Position the camera such that the leaves/branch were set fully against the blue sky with the bulding (?) cutting diagonally across the lower third woul really enhance the subject and visual interest.', '2007-01-30 14:24:48.000000', NULL, 1),
(3303404, 456192, 45519, '<td valign="top">Beautifully captured and most excellent contribution to the challenge.  This one truly stands ''above'' the crowd.</td>', 'Beautifully captured and most excellent contribution to the challenge.  This one truly stands ''above'' the crowd.', '2007-01-30 14:25:52.000000', NULL, 1),
(3303407, 457729, 45519, '<td valign="top">Outstanding from both a technical standpoint -- excellent composition, exposure and b&amp;w treatment (especially considering the ME rules this challenge) -- and from a subject standpoint.  My only *10* thus far.</td>', 'Outstanding from both a technical standpoint -- excellent composition, exposure and b&w treatment (especially considering the ME rules this challenge) -- and from a subject standpoint.  My only *10* thus far.', '2007-01-30 14:27:42.000000', NULL, 1),
(3303413, 458375, 45519, '<td valign="top">Not sure if being over exposed, with clipped highlights, hurts or ultimately helps this nicely seen and captured scene.  Works for me.</td>', 'Not sure if being over exposed, with clipped highlights, hurts or ultimately helps this nicely seen and captured scene.  Works for me.', '2007-01-30 14:29:24.000000', NULL, 1),
(3303417, 458587, 45519, '<td valign="top">Nice lighting, tones and composition.  Well done.</td>', 'Nice lighting, tones and composition.  Well done.', '2007-01-30 14:30:11.000000', NULL, 1),
(3303426, 458148, 45519, '<td valign="top">A lot of graphical interest here and the angle gives it nice architectural abstract potential ... but it doesn''t say minimalism to me, at least not artistically/photographically.  All the geometric interplay and variety of textures overshadows the otherwise minimal subject matter.</td>', 'A lot of graphical interest here and the angle gives it nice architectural abstract potential ... but it doesn''t say minimalism to me, at least not artistically/photographically.  All the geometric interplay and variety of textures overshadows the otherwise minimal subject matter.', '2007-01-30 14:33:18.000000', NULL, 1),
(3303430, 458029, 45519, '<td valign="top">Beautiful color and light!  Nicely done.</td>', 'Beautiful color and light!  Nicely done.', '2007-01-30 14:33:58.000000', NULL, 1),
(3303443, 458740, 45519, '<td valign="top">Fantastic shot and b&amp;w treatment, regardless of the challenge topic and especially given the Minimal Editing rules.  Works for me ... now clean your sensor and perpare a nicely post process version for after the challenge! :)</td>', 'Fantastic shot and b&w treatment, regardless of the challenge topic and especially given the Minimal Editing rules.  Works for me ... now clean your sensor and perpare a nicely post process version for after the challenge! :)', '2007-01-30 14:37:27.000000', NULL, 1),
(3303446, 456322, 45519, '<td valign="top">Nice graphic ... and good eye to spot it (assuming it isn''t staged).  Great contrast too; love how rich it is.</td>', 'Nice graphic ... and good eye to spot it (assuming it isn''t staged).  Great contrast too; love how rich it is.', '2007-01-30 14:38:45.000000', NULL, 1),
(3303449, 458309, 45519, '<td valign="top">Nice timing and capture.  Bit of a stretch for the challenge IMO -- minimal subject matter but not really minimalism -- but well done nonetheless.</td>', 'Nice timing and capture.  Bit of a stretch for the challenge IMO -- minimal subject matter but not really minimalism -- but well done nonetheless.', '2007-01-30 14:39:51.000000', NULL, 1),
(3303451, 456890, 45519, '<td valign="top">Excellent use of DOF and nicely composed.  Well seen and captured.</td>', 'Excellent use of DOF and nicely composed.  Well seen and captured.', '2007-01-30 14:40:25.000000', NULL, 1),
