(3303475, 457973, 45519, '<td valign="top">Cool shot ... would love to see this with the same light (the lighting here is great) and composition (maybe with the horizon slightly higher) but clear blus skies (or maybe a single, wafty cloud).</td>', 'Cool shot ... would love to see this with the same light (the lighting here is great) and composition (maybe with the horizon slightly higher) but clear blus skies (or maybe a single, wafty cloud).', '2007-01-30 14:48:12.000000', NULL, 1),
(3303477, 457878, 45519, '<td valign="top">Great color and light ... well done.</td>', 'Great color and light ... well done.', '2007-01-30 14:48:38.000000', NULL, 1),
