INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3315925, 458299, 50695, '<td valign="top">I love the skewed perspective and odd POV. I have a poem with same title.<br/> <br/>Crossing<br/> <br/> <br/>This is the chorus.<br/>The crosses are here. Arise.<br/>Telephone poles are not a coincidence.<br/> <br/>Someone familiar has not seen you.<br/>She turns around. The meaningless symbol<br/>breaks your heart. Your imagined world<br/>is attacking you from pointed spaceships,<br/>like rain squeezing through a window.<br/> <br/>This is the chorus.<br/>The crosses are here.<br/>The telephone poles are real.<br/> <br/>A trainyard of pieces of trains<br/>and pieces of track. They go.<br/>You merely continue. You are inside<br/>a whole train. You are so sure<br/>that you are parallel to your life.<br/> <br/>But the crosses are here. Rise.<br/>This is the chorus.<br/>The telephone poles died for a reason.<br/> <br/>10</td>', 'I love the skewed perspective and odd POV. I have a poem with same title. Crossing  This is the chorus.The crosses are here. Arise.Telephone poles are not a coincidence. Someone familiar has not seen you.She turns around. The meaningless symbolbreaks your heart. Your imagined worldis attacking you from pointed spaceships,like rain squeezing through a window. This is the chorus.The crosses are here.The telephone poles are real. A trainyard of pieces of trainsand pieces of track. They go.You merely continue. You are insidea whole train. You are so surethat you are parallel to your life. But the crosses are here. Rise.This is the chorus.The telephone poles died for a reason. 10', '2007-02-01 22:00:01.000000', NULL, 1),
(3315929, 458575, 50695, '<td valign="top">well done. 8</td>', 'well done. 8', '2007-02-01 22:00:36.000000', NULL, 1),
(3315940, 458309, 50695, '<td valign="top">Amazing that you did this with no editing!! wow! 9</td>', 'Amazing that you did this with no editing!! wow! 9', '2007-02-01 22:03:02.000000', NULL, 1),
(3315949, 455393, 50695, '<td valign="top">this is like a metaphor for Minimalism, and it''s just how some people feel when they look at Minimalist art! Very funny. 9</td>', 'this is like a metaphor for Minimalism, and it''s just how some people feel when they look at Minimalist art! Very funny. 9', '2007-02-01 22:04:18.000000', NULL, 1),
